    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        guess_set = {u * n + v for u, v in guesses}

        parent = [-1] * n
        parent[0] = -2
        stack = [0]
        correct = 0

