class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        MOD = 10**9 + 7
        dp = [0] * (target + 1)
        dp[0] = 1
        new_dp = [0] * (target + 1)

        for count, marks in types:
            threshold = (count + 1) * marks
            limit = min(threshold, target + 1)
            for r in range(marks):
                window_sum = 0
                for i in range(r, limit, marks):
                    window_sum += dp[i]
                    new_dp[i] = window_sum % MOD
                for i in range(threshold + r, target + 1, marks):
                    window_sum += dp[i] - dp[i - threshold]
                    new_dp[i] = window_sum % MOD
            dp, new_dp = new_dp, dp

        return dp[target]

