class Solution:
    def beautifulSubsets(self, nums: List[int], k: int) -> int:
        counts = Counter(nums)
        groups = defaultdict(list)
        for x in counts:
            groups[x % k].append(x)

        total_ways = 1
        for group in groups.values():
            group.sort()
            dp0, dp1 = 1, 0
            prev = None

            for x in group:
                c = counts[x]
                if prev is not None and x - prev == k:
                    dp0, dp1 = dp0 + dp1, dp0 * ((1 << c) - 1)
                else:
                    if prev is not None:
                        total_ways *= (dp0 + dp1)
                    dp0, dp1 = 1, (1 << c) - 1
                prev = x

            total_ways *= (dp0 + dp1)

        return total_ways - 1

