class Solution:
    def beautifulPair(self, nums1: List[int], nums2: List[int]) -> List[int]:
        n = len(nums1)
        points = {}
        best_pair = None

        for i in range(n):
            coord = (nums1[i], nums2[i])
            if coord in points:
                p = (points[coord], i)
                if best_pair is None or p < best_pair:
                    best_pair = p
            else:
                points[coord] = i

        if best_pair is not None:
            return list(best_pair)

        P = sorted((nums1[i], nums2[i], i) for i in range(n))

        def solve(left, right):
            if right - left <= 3:
                best_d = 10**18
                best_p = (10**18, 10**18)
                for i in range(left, right):
                    x1, y1, id1 = P[i]
                    for j in range(i + 1, right):
                        x2, y2, id2 = P[j]
                        d = abs(x1 - x2) + abs(y1 - y2)
                        u, v = (id1, id2) if id1 < id2 else (id2, id1)
                        if d < best_d or (d == best_d and (u, v) < best_p):
                            best_d = d
                            best_p = (u, v)
                return best_d, best_p

            mid = (left + right) // 2
            mid_x = P[mid][0]

            d1, p1 = solve(left, mid)
            d2, p2 = solve(mid, right)

            if d1 < d2 or (d1 == d2 and p1 < p2):
                d, p = d1, p1
            else:
                d, p = d2, p2

            strip = [pt for pt in P[left:right] if abs(pt[0] - mid_x) <= d]
            strip.sort(key=itemgetter(1))

            for i in range(len(strip)):
                p1_x, p1_y, p1_id = strip[i]
                for j in range(i + 1, len(strip)):
                    p2_x, p2_y, p2_id = strip[j]
                    dy = p2_y - p1_y

                    if dy > d:
                        break

                    dist = abs(p1_x - p2_x) + dy
                    u, v = (p1_id, p2_id) if p1_id < p2_id else (p2_id, p1_id)

                    if dist < d or (dist == d and (u, v) < p):
                        d = dist
                        p = (u, v)

            return d, p

        _, ans = solve(0, n)
        return list(ans)

