class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        ones = nums.count(1)
        if ones:
            return n - ones

        min_len = n + 1
        gcds = {}
        new_gcds = {}

        for j, num in enumerate(nums):
            new_gcds.clear()
            new_gcds[num] = j
            for g, i in gcds.items():
                ng = gcd(g, num)
                if ng not in new_gcds or i > new_gcds[ng]:
                    new_gcds[ng] = i
            if 1 in new_gcds:
                l = j - new_gcds[1] + 1
                if l < min_len:
                    min_len = l
            gcds, new_gcds = new_gcds, gcds

        return min_len + n - 2 if min_len <= n else -1

