class Solution:
    def findMaxFish(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        max_fish = 0

        for r in range(m):
            for c in range(n):
                if grid[r][c] > 0:
                    fish = grid[r][c]
                    grid[r][c] = 0
                    stack = [(r, c)]

                    while stack:
                        cr, cc = stack.pop()

                        if cr > 0 and grid[cr - 1][cc] > 0:
                            fish += grid[cr - 1][cc]
                            grid[cr - 1][cc] = 0
                            stack.append((cr - 1, cc))
                        if cr < m - 1 and grid[cr + 1][cc] > 0:
                            fish += grid[cr + 1][cc]
                            grid[cr + 1][cc] = 0
                            stack.append((cr + 1, cc))
                        if cc > 0 and grid[cr][cc - 1] > 0:
                            fish += grid[cr][cc - 1]
                            grid[cr][cc - 1] = 0
                            stack.append((cr, cc - 1))
                        if cc < n - 1 and grid[cr][cc + 1] > 0:
                            fish += grid[cr][cc + 1]
                            grid[cr][cc + 1] = 0
                            stack.append((cr, cc + 1))

                    if fish > max_fish:
                        max_fish = fish

        return max_fish

