            for p in player:
                score += p * (2 if double_count else 1)
                double_count = 2 if p == 10 else (double_count - 1 if double_count else 0)
            return score

        score1 = get_score(player1)
        score2 = get_score(player2)

        if score1 == score2:
            return 0
        return 1 if score1 > score2 else 2

