class Solution:
    def minimumCost(self, start: List[int], target: List[int], specialRoads: List[List[int]]) -> int:
        start_t, target_t = tuple(start), tuple(target)
        points = {start_t, target_t}
        for x1, y1, x2, y2, _ in specialRoads:
            points.add((x1, y1))
            points.add((x2, y2))
        node_to_idx = {p: i for i, p in enumerate(points)}

        N = len(node_to_idx)
        nodes = list(node_to_idx)

        special_adj = [[] for _ in range(N)]
        for x1, y1, x2, y2, cost in specialRoads:
            u, v = node_to_idx[(x1, y1)], node_to_idx[(x2, y2)]
            special_adj[u].append((v, cost))

        start_idx, target_idx = node_to_idx[start_t], node_to_idx[target_t]

        dist = [float('inf')] * N
        dist[start_idx] = 0
        pq = [(0, start_idx)]
        heappush = heapq.heappush

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            if u == target_idx:
                return d

            xu, yu = nodes[u]
            du = dist[u]

            for v, (xv, yv) in enumerate(nodes):
                new_dist = du + abs(xu - xv) + abs(yu - yv)
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heappush(pq, (new_dist, v))

            for v, cost in special_adj[u]:
                new_dist = du + cost
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heappush(pq, (new_dist, v))

        return dist[target_idx]

