    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        colors = [0] * n
        count = 0
        ans = [0] * len(queries)

        for i, (index, color) in enumerate(queries):
            old_color = colors[index]
            if old_color == color:
                ans[i] = count
                continue

            colors[index] = color

            if index > 0:
                left = colors[index - 1]
                if old_color and left == old_color:
                    count -= 1
                if left == color:
                    count += 1

            if index < n - 1:
                right = colors[index + 1]
                if old_color and right == old_color:
                    count -= 1
                if right == color:
                    count += 1

            ans[i] = count

        return ans

