        adj = [[] for _ in range(n)]
        degree = [0] * n

        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
            degree[u] += 1
            degree[v] += 1

        ans = 0

        for i in range(n):
            if degree[i] >= 0:
                stack = [i]
                degree_sum = degree[i]
                degree[i] = -1
                v_count = 0

                while stack:
                    u = stack.pop()
                    v_count += 1

                    for v in adj[u]:
                        if degree[v] >= 0:
                            degree_sum += degree[v]
                            degree[v] = -1
                            stack.append(v)

                if degree_sum == v_count * (v_count - 1):
                    ans += 1

        return ans

