class Solution:
    def minOperations(self, nums: List[int], x: int, y: int) -> int:
        low, high, diff = 0, (max(nums) + y - 1) // y, x - y

        while low < high:
            mid = (low + high) >> 1
            ky = mid * y

            ops_needed = 0
            for num in nums:
                if num > ky:
                    ops_needed += (num - ky + diff - 1) // diff
                    if ops_needed > mid:
                        low = mid + 1
                        break
            else:
                high = mid

        return low

