class Solution:
    def maxIncreasingCells(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])

        cells = sorted((mat[i][j], i, j) for i in range(m) for j in range(n))

        row_max = [0] * m
        col_max = [0] * n
        row_updates = [0] * m
        col_updates = [0] * n

        for _, group in groupby(cells, key=itemgetter(0)):
            group = list(group)

            for _, r, c in group:
                rm = row_max[r]
                cm = col_max[c]
                dp_val = 1 + (rm if rm > cm else cm)
                if dp_val > row_updates[r]:
                    row_updates[r] = dp_val
                if dp_val > col_updates[c]:
                    col_updates[c] = dp_val

            for _, r, c in group:
                ru = row_updates[r]
                if ru > row_max[r]:
                    row_max[r] = ru
                row_updates[r] = 0
                cu = col_updates[c]
                if cu > col_max[c]:
                    col_max[c] = cu
                col_updates[c] = 0

        return max(max(row_max), max(col_max))

