class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def solve(num_str: str) -> int:
            digits = [int(c) for c in num_str]
            n = len(digits)
            memo = [[[-1] * 2 for _ in range(max_sum + 1)] for _ in range(n)]

            def dp(pos: int, dsum: int, tight: int) -> int:
                if dsum > max_sum:
                    return 0
                if pos == n:
                    return 1 if dsum >= min_sum else 0
                if memo[pos][dsum][tight] != -1:
                    return memo[pos][dsum][tight]

                limit = digits[pos] if tight else 9
                res = 0
                if tight:
                    for d in range(limit):
                        res += dp(pos + 1, dsum + d, 0)
                    res += dp(pos + 1, dsum + limit, 1)
                else:
                    for d in range(10):
                        res += dp(pos + 1, dsum + d, 0)

                res %= MOD
                memo[pos][dsum][tight] = res
                return res

            return dp(0, 0, 1)

        return (solve(num2) - solve(str(int(num1) - 1))) % MOD

