class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        char_masks = [1 << (ord(c) - 97) for c in s]
        mask = [0] * n
        queue = [0]

        for u in queue:
            for v in children[u]:
                mask[v] = mask[u] ^ char_masks[v]
                queue.append(v)

        freq = Counter(mask)

        ans = 0
        cross = 0
        for m, count in freq.items():
            ans += count * (count - 1) // 2
            for k in range(26):
                m2 = m ^ (1 << k)
                if m2 in freq:
                    cross += count * freq[m2]

        return ans + cross // 2

class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(s1: str, s2: str) -> str:
            if s2 in s1:
                return s1
            if s1 in s2:
                return s2
            for i in range(min(len(s1), len(s2)), 0, -1):
                if s1[-i:] == s2[:i]:
                    return s1 + s2[i:]
            return s1 + s2

        best = merge(merge(a, b), c)
        l_best = len(best)

        for x, y, z in ((a, c, b), (b, a, c), (b, c, a), (c, a, b), (c, b, a)):
            res = merge(merge(x, y), z)
            l_res = len(res)
            if l_res < l_best or (l_res == l_best and res < best):
                best = res
                l_best = l_res

        return best

