class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        positions = defaultdict(list)
        for i, num in enumerate(nums):
            positions[num].append(i)

        def get_time(pos):
            max_gap = pos[0] + n - pos[-1]
            for i in range(len(pos) - 1):
                gap = pos[i + 1] - pos[i]
                if gap > max_gap:
                    max_gap = gap
            return max_gap // 2

        return min(map(get_time, positions.values()))

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        S1, S2 = sum(nums1), sum(nums2)
        order = sorted(range(n), key=nums2.__getitem__)
        dp = [0] * (n + 1)

        for i in range(n):
            idx = order[i]
            a, b = nums1[idx], nums2[idx]
            val = a + (i + 1) * b
            for j in range(i + 1, 0, -1):
                new_val = dp[j - 1] + val
                if new_val > dp[j]:
                    dp[j] = new_val
                val -= b

        current_sum = S1
        for t in range(n + 1):
            if current_sum - dp[t] <= x:
                return t
            current_sum += S2

        return -1

