class Solution:
    def maximumSafenessFactor(self, grid: List[List[int]]) -> int:
        n = len(grid)

        if grid[0][0] == 1 or grid[n - 1][n - 1] == 1:
            return 0

        n2 = n * n
        dist = [-1] * n2
        queue = deque()

        for r in range(n):
            row = grid[r]
            base = r * n
            for c in range(n):
                if row[c] == 1:
                    idx = base + c
                    dist[idx] = 0
                    queue.append(idx)

        col_limit = n - 1
        row_limit = n * col_limit

        while queue:
            pos = queue.popleft()
            d = dist[pos] + 1

            if pos % n != col_limit:
                npos = pos + 1
                if dist[npos] == -1:
                    dist[npos] = d
                    queue.append(npos)
            if pos % n:
                npos = pos - 1
                if dist[npos] == -1:
                    dist[npos] = d
                    queue.append(npos)
            if pos < row_limit:
                npos = pos + n
                if dist[npos] == -1:
                    dist[npos] = d
                    queue.append(npos)
            if pos >= n:
                npos = pos - n
                if dist[npos] == -1:
                    dist[npos] = d
                    queue.append(npos)

        target = n2 - 1
        heap = [(-dist[0], 0)]
        visited = bytearray(n2)
        visited[0] = 1

        while heap:
            d, pos = heapq.heappop(heap)
            d = -d

            if pos == target:
                return d

            if pos % n != col_limit:
                npos = pos + 1
                if not visited[npos]:
                    visited[npos] = 1
                    nd = dist[npos]
                    heapq.heappush(heap, (-(d if d < nd else nd), npos))
            if pos % n:
                npos = pos - 1
                if not visited[npos]:
                    visited[npos] = 1
                    nd = dist[npos]
                    heapq.heappush(heap, (-(d if d < nd else nd), npos))
            if pos < row_limit:
                npos = pos + n
                if not visited[npos]:
                    visited[npos] = 1
                    nd = dist[npos]
                    heapq.heappush(heap, (-(d if d < nd else nd), npos))
            if pos >= n:
                npos = pos - n
                if not visited[npos]:
                    visited[npos] = 1
                    nd = dist[npos]
                    heapq.heappush(heap, (-(d if d < nd else nd), npos))

        return 0

class Solution:
    def doubleIt(self, head: Optional[ListNode]) -> Optional[ListNode]:
        tail = head
        prev = None
        curr = head
        while curr:
            curr.next, prev, curr = prev, curr, curr.next
        head = prev

        carry = 0
        curr = head
        while curr:
            carry, curr.val = divmod(curr.val * 2 + carry, 10)
            curr = curr.next

        if carry:
            tail.next = ListNode(carry)

        prev = None
        curr = head
        while curr:
            curr.next, prev, curr = prev, curr, curr.next

        return prev

