class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        from functools import lru_cache

        @lru_cache(None)
        def dp_free(rem, started, diff, mod):
            if not rem:
                return 1 if (started and not diff and not mod) else 0
            res = 0
            for d in range(10):
                if started or d:
                    res += dp_free(rem - 1, True, diff + 1 - (d & 1) * 2, (mod * 10 + d) % k)
                else:
                    res += dp_free(rem - 1, False, diff, mod)
            return res

        @lru_cache(None)
        def dp_tight(digits, pos, started, diff, mod):
            if pos == len(digits):
                return 1 if (started and not diff and not mod) else 0

            limit = digits[pos]
            res = 0
            rem = len(digits) - pos - 1

            for d in range(limit):
                if started or d:
                    res += dp_free(rem, True, diff + 1 - (d & 1) * 2, (mod * 10 + d) % k)
                else:
                    res += dp_free(rem, False, diff, mod)

            d = limit
            if started or d:
                res += dp_tight(digits, pos + 1, True, diff + 1 - (d & 1) * 2, (mod * 10 + d) % k)
            else:
                res += dp_tight(digits, pos + 1, False, diff, mod)

            return res

        def count(n):
            if n <= 0:
                return 0
            return dp_tight(tuple(map(int, str(n))), 0, False, 0, 0)

        return count(high) - count(low - 1)

