class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        count = [0] * 31
        for num in nums:
            if 0 <= (bl := num.bit_length() - 1) < 31:
                count[bl] += 1

        operations = 0
        for i in range(30):
            if not ((target >> i) & 1):
                count[i + 1] += count[i] >> 1
                continue

            if count[i]:
                count[i] -= 1
                count[i + 1] += count[i] >> 1
                continue

            for j in range(i + 1, 31):
                if count[j]:
                    break
            else:
                return -1

            operations += j - i
            count[j] -= 1
            for k in range(i + 1, j):
                count[k] += 1

        if (target >> 30) & 1 and not count[30]:
            return -1

        return operations

