        max_alloys = 0
        UPPER_BOUND = 200_000_001

        for comp in composition:
            left, right = max_alloys, UPPER_BOUND

            while left <= right:
                mid = (left + right) // 2
                current_cost = 0

                for c, s, co in zip(comp, stock, cost):
                    needed = mid * c
                    if needed > s:
                        current_cost += (needed - s) * co
                        if current_cost > budget:
