class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)

        def compute_sums(reverse=False):
            sums = [0] * n
            stack = []
            for i in (range(n - 1, -1, -1) if reverse else range(n)):
                while stack and maxHeights[stack[-1]] >= maxHeights[i]:
                    stack.pop()
                if stack:
                    j = stack[-1]
                    sums[i] = sums[j] + abs(i - j) * maxHeights[i]
                else:
                    sums[i] = (n - i if reverse else i + 1) * maxHeights[i]
                stack.append(i)
            return sums

        prefix = compute_sums()
        suffix = compute_sums(reverse=True)

        return max(prefix[i] + suffix[i] - maxHeights[i] for i in range(n))

