class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        if not n:
            return []

        dp = [1] * n
        prev = [-1] * n
        lengths = [len(w) for w in words]

        for i in range(n):
            wi, gi, lwi = words[i], groups[i], lengths[i]
            dpi, pi = 1, -1
            for j in range(i):
                if gi != groups[j] and lwi == lengths[j] and self._is_hamming_1(wi, words[j]):
                    if dp[j] >= dpi:
                        dpi = dp[j] + 1
                        pi = j
            dp[i], prev[i] = dpi, pi

        max_idx = max(range(n), key=dp.__getitem__)

        ans = []
        curr = max_idx
        while curr != -1:
            ans.append(words[curr])
            curr = prev[curr]

        return ans[::-1]

    @staticmethod
    def _is_hamming_1(w1: str, w2: str) -> bool:
        diff = 0
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

