class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # Sieve-like divisor computation - O(n log n) instead of O(n^2)
        divisors = [[] for _ in range(n + 1)]
        for d in range(1, n // 2 + 1):
            for L in range(2 * d, n + 1, d):
                divisors[L].append(d)

        # Precompute cost[i][j] = min changes to make s[i..j] a semi-palindrome
        INF = 10**9
        cost = [[INF] * n for _ in range(n)]

        for i in range(n):
            cost_i = cost[i]
            for j in range(i + 1, n):
                L = j - i + 1
                min_cost = INF

                for d in divisors[L]:
                    total_cost = 0
                    k_groups = L // d
                    half = k_groups >> 1
                    for r in range(d):
                        left = i + r
                        right = left + (k_groups - 1) * d
                        for _ in range(half):
                            if s[left] != s[right]:
                                total_cost += 1
                            left += d
                            right -= d
                        if total_cost >= min_cost:
                            break
                    if total_cost < min_cost:
                        min_cost = total_cost

                cost_i[j] = min_cost

        # DP with space optimization - O(n) space instead of O(nk)
        dp = [INF] * (n + 1)
        dp[0] = 0

        for j in range(1, k + 1):
            new_dp = [INF] * (n + 1)
            lower = 2 * (j - 1)
            for i in range(2 * j, n + 1):
                min_val = INF
                target = i - 1
                for m in range(lower, target):
                    dp_m = dp[m]
                    if dp_m < INF:
                        val = dp_m + cost[m][target]
                        if val < min_val:
                            min_val = val
                new_dp[i] = min_val
            dp = new_dp

        return dp[n]

