class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        m = len(queries)
        ans = [-1] * m

        deferred = []
        for i, (a, b) in enumerate(queries):
            if a == b:
                ans[i] = a
            else:
                if a > b:
                    a, b = b, a
                if heights[a] < heights[b]:
                    ans[i] = b
                else:
                    deferred.append((b, heights[a], i))

        deferred.sort(reverse=True)

        stack = []
        ptr = 0
        num_deferred = len(deferred)

        for i in range(n - 1, -1, -1):
            while ptr < num_deferred and deferred[ptr][0] == i:
                target = deferred[ptr][1]
                qi = deferred[ptr][2]

                lo, hi = 0, len(stack) - 1
                res = -1
                while lo <= hi:
                    mid = (lo + hi) >> 1
                    if heights[stack[mid]] > target:
                        res = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1
                if res != -1:
                    ans[qi] = stack[res]
                ptr += 1

            h_i = heights[i]
            while stack and heights[stack[-1]] <= h_i:
                stack.pop()
            stack.append(i)

        return ans

