class Solution:
    def maxGcdSum(self, nums: List[int], k: int) -> int:
        prefix_sum = [0] + list(accumulate(nums))
        ans = 0
        current_states = {}

        for j, num in enumerate(nums):
            new_states = {num: j}
            for g, start in current_states.items():
                new_g = gcd(g, num)
                if new_g not in new_states or start < new_states[new_g]:
                    new_states[new_g] = start

            psum_j1 = prefix_sum[j + 1]
            min_start = j - k + 1
            for g, start in new_states.items():
                if start <= min_start:
                    val = g * (psum_j1 - prefix_sum[start])
                    if val > ans:
                        ans = val
            current_states = new_states

        return ans

