        INF = 10**9
        adj = [[INF] * n for _ in range(n)]
        for i in range(n):
            adj[i][i] = 0
        for u, v, w in roads:
            if w < adj[u][v]:
                adj[u][v] = w
                adj[v][u] = w

        ans = 0
        dist = [[INF] * n for _ in range(n)]

        for mask in range(1 << n):
            active = [i for i in range(n) if mask & (1 << i)]
            if len(active) <= 1:
                ans += 1
                continue

            for i in active:
                di = dist[i]
                adj_i = adj[i]
                for j in active:
                    di[j] = adj_i[j]

