                    di = dist[i]
                    dik = di[k]
                    for j in active:
                        val = dik + dk[j]
                        if val < di[j]:
                            di[j] = val

            for i in active:
                di = dist[i]
                for j in active:
                    if di[j] > maxDistance:
                        break
                else:
                    continue
                break
            else:
                ans += 1

