        n = len(nums)

        prefix_len = 1
        while prefix_len < n and nums[prefix_len] > nums[prefix_len - 1]:
            prefix_len += 1

        if prefix_len == n:
            return n * (n + 1) // 2

        suffix_start = n - 1
        while suffix_start > 0 and nums[suffix_start - 1] < nums[suffix_start]:
            suffix_start -= 1

        count = n - suffix_start + 1
        j_ptr = suffix_start

        for i in range(1, prefix_len + 1):
            while j_ptr < n and nums[j_ptr] <= nums[i - 1]:
                j_ptr += 1
            count += n - max(i, j_ptr - 1)

        return count

