class Solution:
    def selfDivisiblePermutationCount(self, n: int) -> int:
        from math import gcd

        valid_masks = [
            sum(1 << (num - 1) for num in range(1, n + 1) if gcd(num, pos + 1) == 1)
            for pos in range(n)
        ]

        dp, new_dp = {0: 1}, {}
        for vmask in valid_masks:
            new_dp.clear()
            for mask, count in dp.items():
                available = vmask & ~mask
                while available:
                    bit = available & -available
                    new_mask = mask | bit
                    new_dp[new_mask] = new_dp.get(new_mask, 0) + count
                    available &= available - 1
            dp, new_dp = new_dp, dp

        return dp[(1 << n) - 1]

