        if x <= y:
            return y - x

        max_val = x + 11
        dist = [-1] * (max_val + 1)
        dist[x] = 0
        queue = deque([x])

        while queue:
            curr = queue.popleft()
            d = dist[curr] + 1

            for nxt in (
                curr // 11 if not curr % 11 else -1,
                curr // 5 if not curr % 5 else -1,
                curr - 1,
