class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_up_to(n: int) -> int:
            if n < 0:
                return 0
            base = limit + 1
            s_str = str(n)
            m = len(s_str)

            ans = base ** (m - 1)
            power_val = ans
            for i, char in enumerate(s_str):
                d = int(char)
                cap = min(d, base)
                ans += (cap - 1 if i == 0 else cap) * power_val
                if d > limit:
                    break
                power_val //= base
            else:
                ans += 1
            return ans

        len_s = len(s)
        s_val = int(s)
        power = 10 ** len_s

        diff_min = start - s_val
        k_min = 0 if diff_min <= 0 else (diff_min + power - 1) // power
        k_max = (finish - s_val) // power

        if k_max < k_min:
            return 0

        return count_up_to(k_max) - count_up_to(k_min - 1)

