class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        result = [0] * n
        for i in range(1, n + 1):
            ix1, iy1 = abs(i - x) + 1, abs(i - y) + 1
            for j in range(1, n + 1):
                if i != j:
                    result[min(abs(i - j), ix1 + abs(y - j), iy1 + abs(x - j)) - 1] += 1
        return result

