class Solution:
    def maximumProcessableQueries(self, nums: List[int], queries: List[int]) -> int:
        n = len(nums)
        m = len(queries)

        dp = [[0] * n for _ in range(n)]
        new_dp = [[0] * n for _ in range(n)]

        for k in range(m - 1, -1, -1):
            q = queries[k]

            for i in range(n):
                new_dp[i][i] = 1 if nums[i] >= q else 0

            for length in range(1, n):
                max_val = length + 1
                for i in range(n - length):
                    j = i + length

                    res = new_dp[i + 1][j]
                    if new_dp[i][j - 1] > res:
                        res = new_dp[i][j - 1]

                    if res < max_val:
                        if nums[i] >= q:
                            v = dp[i + 1][j] + 1
                            if v > res:
                                res = v
                        if res < max_val and nums[j] >= q:
                            v = dp[i][j - 1] + 1
                            if v > res:
                                res = v

                    new_dp[i][j] = res

            dp, new_dp = new_dp, dp

        return dp[0][n - 1]

