class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        target = len(nums) - k
        mask = 0
        for b in range(29, -1, -1):
            test = mask | (1 << b)
            count = 0
            cur = test
            for num in nums:
                cur &= num
                if not cur:
                    count += 1
                    if count == target:
                        break
                    cur = test
            if count == target:
                mask = test
        return 0x3FFFFFFF ^ mask

class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
        points.sort(key=lambda p: (p[0], -p[1]))
        n, count, neg_inf = len(points), 0, float('-inf')
        for i in range(n - 1):
            y_i, max_y = points[i][1], neg_inf
            for j in range(i + 1, n):
                y_j = points[j][1]
                if max_y < y_j <= y_i:
                    count += 1
                    max_y = y_j
        return count

class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        for offset in range(k, n, k):
            if word.startswith(word[offset:]):
                return offset // k
        return (n + k - 1) // k

class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        pi = [0] * n
        for i in range(1, n):
            j = pi[i - 1]
            while j and word[i] != word[j]:
                j = pi[j - 1]
            pi[i] = j + (word[i] == word[j])

        x = pi[-1]
        while x:
            if not (n - x) % k:
                return (n - x) // k
            x = pi[x - 1]
        return -(-n // k)

