class Solution:
    def modifiedMatrix(self, matrix: List[List[int]]) -> List[List[int]]:
        col_max = matrix[0][:]
        for row in matrix[1:]:
            for j, val in enumerate(row):
                if val > col_max[j]:
                    col_max[j] = val
        return [[col_max[j] if val == -1 else val for j, val in enumerate(row)] for row in matrix]

class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        from collections import Counter

        char_count = Counter()
        for word in words:
            char_count.update(word)

        total_pairs = 0
        total_singles = 0
        for count in char_count.values():
            total_pairs += count >> 1
            total_singles += count & 1

        count = 0
        for L in sorted(len(word) for word in words):
            pairs_needed = L >> 1

            if total_pairs < pairs_needed:
                break

            if L & 1:
                if total_singles > 0:
                    total_singles -= 1
                elif total_pairs > pairs_needed:
                    total_pairs -= 1
                    total_singles += 1
                else:
                    break
            total_pairs -= pairs_needed

            count += 1

        return count

