class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)

        # At most 3 possible target scores from the first operation
        targets = {
            nums[0] + nums[1],
            nums[-1] + nums[-2],
            nums[0] + nums[-1]
        }

        best = 0

        for target in targets:
            # Use two 1D arrays to reduce memory from O(n^2) to O(n)
            dp1 = [0] * (n + 1)
            dp2 = [0] * (n + 1)

            # k represents the total number of elements removed so far
            # We compute layer by layer from the end (k = n-2) down to the start
            for k in range(n - 2, (n % 2) - 1, -2):
                for L in range(k + 1):
                    right = n - 1 - k + L

                    res = 0

                    # Option 1: remove first two elements
                    if nums[L] + nums[L + 1] == target:
                        res = 1 + dp1[L + 2]

                    # Option 2: remove last two elements
                    if nums[right] + nums[right - 1] == target:
                        val = 1 + dp1[L]
                        if val > res:
                            res = val

                    # Option 3: remove first and last elements
                    if nums[L] + nums[right] == target:
                        val = 1 + dp1[L + 1]
                        if val > res:
                            res = val

                    dp2[L] = res

                # Swap arrays for the next iteration
                dp1, dp2 = dp2, dp1

            if dp1[0] > best:
                best = dp1[0]

            # Early exit if we've used all elements
            if best == n // 2:
                break

        return best

class Solution:
    def maxSelectedElements(self, nums: List[int]) -> int:
        nums.sort()
        dp = {}
        dp_get = dp.get
        for x in nums:
            px = dp_get(x, 0)
            dp[x] = max(px, dp_get(x - 1, 0) + 1)
            dp[x + 1] = max(dp_get(x + 1, 0), px + 1)
        return max(dp.values(), default=0)

