class Solution:
    def gameResult(self, head: Optional[ListNode]) -> str:
        score = 0
        while head and head.next:
            score += 1 if head.next.val > head.val else -1
            head = head.next.next
        return "Odd" if score > 0 else "Even" if score < 0 else "Tie"

