class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        result = [0] * n
        stack = []

        for c in range(n):
            running_sum = pairs = 0
            for neighbor, weight in adj[c]:
                count = 0
                stack += (neighbor, c, weight)
                while stack:
                    dist = stack.pop()
                    parent = stack.pop()
                    node = stack.pop()
                    if not dist % signalSpeed:
                        count += 1
                    for next_node, next_weight in adj[node]:
                        if next_node != parent:
                            stack += (next_node, node, dist + next_weight)
                pairs += count * running_sum
                running_sum += count
            result[c] = pairs

        return result

