class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        total = sum(nums)
        diffs = sorted(((x ^ k) - x for x in nums), reverse=True)

        it = iter(diffs)
        for d1, d2 in zip(it, it):
            pair = d1 + d2
            if pair <= 0:
                break
            total += pair

        return total

