class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)

        # Suffix max: suffix_max[i] = max(nums[i+1:])
        suffix_max = [0] * n
        cur_max = 0
        for i in range(n - 2, -1, -1):
            if nums[i + 1] > cur_max:
                cur_max = nums[i + 1]
            suffix_max[i] = cur_max

        # Coordinate compression for BIT
        rank = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
        max_rank = len(rank)
        left_bit = [0] * (max_rank + 1)

        ans = 0
        for j in range(n):
            nj = nums[j]
            r = rank[nj]
            smr = suffix_max[j]

            if smr > nj:
                # Query max value with rank < r
                max_left = 0
                pos = r - 1
                while pos > 0:
                    v = left_bit[pos]
                    if v > max_left:
                        max_left = v
                    pos &= pos - 1

                if max_left:
                    val = max_left - nj + smr
                    if val > ans:
                        ans = val

            # Update BIT with nj at rank r (early exit if dominated)
            pos = r
            while pos <= max_rank and nj > left_bit[pos]:
                left_bit[pos] = nj
                pos += pos & (-pos)

        return ans

