class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        from collections import defaultdict

        sub_count = defaultdict(int)
        for s in arr:
            seen = set()
            for length in range(1, len(s) + 1):
                for start in range(len(s) - length + 1):
                    sub = s[start:start + length]
                    if sub not in seen:
                        seen.add(sub)
                        sub_count[sub] += 1

        answer = []
        for s in arr:
            best = ""
            for length in range(1, len(s) + 1):
                min_sub = None
                for start in range(len(s) - length + 1):
                    sub = s[start:start + length]
                    if sub_count[sub] == 1:
                        if min_sub is None or sub < min_sub:
                            min_sub = sub
                if min_sub is not None:
                    best = min_sub
                    break
            answer.append(best)

        return answer

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        count = [0] * 26
        q_count = 0
        for c in s:
            if c == '?':
                q_count += 1
            else:
                count[ord(c) - 97] += 1

        if q_count == 0:
            return s

        pairs = sorted((count[i], i) for i in range(26))
        V = [p[0] for p in pairs]

        for i in range(25):
            if q_count == 0:
                break
            diff = V[i+1] - V[i]
            needed = diff * (i + 1)
            if q_count >= needed:
                q_count -= needed
                V[:i+1] = [V[i+1]] * (i + 1)
            else:
                add, rem = divmod(q_count, i + 1)
                if add:
                    V[:i+1] = [v + add for v in V[:i+1]]
                if rem:
                    V[:rem] = [v + 1 for v in V[:rem]]
                q_count = 0
                break
        else:
            if q_count > 0:
                add, rem = divmod(q_count, 26)
                if add:
                    V = [v + add for v in V]
                if rem:
                    V[:rem] = [v + 1 for v in V[:rem]]

        chosen_counts = [0] * 26
        for k, (init_val, char_idx) in enumerate(pairs):
            chosen_counts[char_idx] = V[k] - init_val

        result = []
        q_idx = 0
        for c in s:
            if c == '?':
                while chosen_counts[q_idx] == 0:
                    q_idx += 1
                result.append(chr(q_idx + 97))
                chosen_counts[q_idx] -= 1
            else:
                result.append(c)

        return ''.join(result)

