class Solution:
    def minimumMoves(self, nums: List[int], k: int, maxChanges: int) -> int:
        pos = [i for i, x in enumerate(nums) if x]
        m = len(pos)

        prefix = [0] * (m + 1)
        for i, p in enumerate(pos):
            prefix[i + 1] = prefix[i] + p

        min_r = max(0, k - maxChanges)
        max_r = min(k, m, max(3, min_r))

        ans = 2 * k if min_r == 0 else float('inf')

        for r in range(max(1, min_r), max_r + 1):
            offset = r >> 1
            base_cost = (k - r) << 1

            if r & 1:
                for i in range(m - r + 1):
                    cost = prefix[i + r] - prefix[i + offset + 1] - prefix[i + offset] + prefix[i] + base_cost
                    if cost < ans:
                        ans = cost
            else:
                for i in range(m - r + 1):
                    cost = pos[i + offset] + prefix[i + r] - prefix[i + offset + 1] - prefix[i + offset] + prefix[i] + base_cost
                    if cost < ans:
                        ans = cost

        return ans

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        left = 0
        max_len = 0
        prev1 = {}
        prev2 = {}

        for right, char in enumerate(s):
            p2 = prev2.get(char, -1)
            if p2 >= left:
                left = p2 + 1

            prev2[char] = prev1.get(char, -1)
            prev1[char] = right

            max_len = max(max_len, right - left + 1)

        return max_len

