class Solution:
    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
        lengths = [len(w) for w in wordsContainer]

        best_overall_idx = 0
        min_len = lengths[0]
        for i, l in enumerate(lengths[1:], 1):
            if l < min_len:
                min_len = l
                best_overall_idx = i

        trie = [{}]
        best_idx = [best_overall_idx]

        for i, word in enumerate(wordsContainer):
            node = 0
            word_len = lengths[i]
            for char in reversed(word):
                children = trie[node]
                if char in children:
                    node = children[char]
                    if word_len < lengths[best_idx[node]]:
                        best_idx[node] = i
                else:
                    node = len(trie)
                    children[char] = node
                    trie.append({})
                    best_idx.append(i)

        ans = []
        for query in wordsQuery:
            node = 0
            for char in reversed(query):
                children = trie[node]
                if char in children:
                    node = children[char]
                else:
                    break
            ans.append(best_idx[node])

        return ans

