class Solution:
    def minimumLevels(self, possible: List[int]) -> int:
        n = len(possible)
        total_sum = 2 * sum(possible) - n
        alice_score = 0

        for i in range(n - 1):
            alice_score += 2 * possible[i] - 1
            if 2 * alice_score > total_sum:
                return i + 1

        return -1

