class Solution:
    def maxBottlesDrunk(self, numBottles: int, numExchange: int) -> int:
        discriminant = (2 * numExchange - 3) ** 2 + 8 * (numBottles - 1)
        exchanges = (3 - 2 * numExchange + math.isqrt(discriminant)) // 2
