class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        max_u = max_u2 = max_v = max_v2 = -float('inf')
        min_u = min_u2 = min_v = min_v2 = float('inf')
        max_u_idx = min_u_idx = max_v_idx = min_v_idx = -1

        for i, (x, y) in enumerate(points):
            u, v = x + y, x - y

            if u > max_u:
                max_u2, max_u = max_u, u
                max_u_idx = i
            elif u > max_u2:
                max_u2 = u

            if u < min_u:
                min_u2, min_u = min_u, u
                min_u_idx = i
            elif u < min_u2:
                min_u2 = u

            if v > max_v:
                max_v2, max_v = max_v, v
                max_v_idx = i
            elif v > max_v2:
                max_v2 = v

            if v < min_v:
                min_v2, min_v = min_v, v
                min_v_idx = i
            elif v < min_v2:
                min_v2 = v

        candidates = {max_u_idx, min_u_idx, max_v_idx, min_v_idx}

        return min(
            max(
                (max_u2 if c == max_u_idx else max_u) - (min_u2 if c == min_u_idx else min_u),
                (max_v2 if c == max_v_idx else max_v) - (min_v2 if c == min_v_idx else min_v)
            )
            for c in candidates
        )

class Solution:
    def maxSubstringLength(self, s: str) -> int:
        n = len(s)

        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        F = list(first.values())
        L = list(last.values())

        limit_A = [n] * len(F)
        for idx, i in enumerate(F):
            for k in range(i, n):
                if first[s[k]] < i:
                    limit_A[idx] = k
                    break

        limit_B = [-1] * len(L)
        for idx, j in enumerate(L):
            for k in range(j, -1, -1):
                if last[s[k]] > j:
                    limit_B[idx] = k
                    break

        ans = -1
        for idx_i, i in enumerate(F):
            lim_a = limit_A[idx_i]
            for idx_j, j in enumerate(L):
                if i <= j and (i, j) != (0, n - 1):
                    if lim_a > j and limit_B[idx_j] < i:
                        length = j - i + 1
                        if length > ans:
                            ans = length

        return ans

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        result = bytearray(s, 'ascii')
        for i in range(len(s)):
            if k <= 0:
                break
            pos = result[i] - 97
            cost = pos if pos <= 13 else 26 - pos
            if k >= cost:
                result[i] = 97
                k -= cost
            else:
                result[i] = 97 + pos - k
                break
        return result.decode()

class Solution:
    def minimumCost(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

        for u, v, w in edges:
            union(u, v)

        comp_and = [-1] * n
        for u, v, w in edges:
            comp_and[find(u)] &= w

        return [comp_and[rs] if (rs := find(s)) == (rt := find(t)) else -1 for s, t in query]

