class Solution:
    def numberOfSubarrays(self, nums: List[int]) -> int:
        vals, cnts = [], []
        ans = 0
        for num in nums:
            while vals and vals[-1] < num:
                vals.pop()
                cnts.pop()
            if vals and vals[-1] == num:
                cnts[-1] += 1
                ans += cnts[-1]
            else:
                vals.append(num)
                cnts.append(1)
                ans += 1
        return ans

