class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        size = 1 << n

        # Precompute LCM for every non-empty subset using dynamic programming
        lcms = [1] * size
        for mask in range(1, size):
            i = (mask & -mask).bit_length() - 1
            prev = lcms[mask ^ (1 << i)]
            lcms[mask] = prev * coins[i] // gcd(prev, coins[i])

        # Count how many distinct amounts are <= x using inclusion-exclusion
        def count(x: int) -> int:
            total = 0
            for mask in range(1, size):
                if mask.bit_count() & 1:
                    total += x // lcms[mask]
                else:
                    total -= x // lcms[mask]
            return total

        # Binary search for the smallest x such that count(x) >= k
        lo, hi = 1, k * min(coins)
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1

        return lo

