class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        ALL_ONES = (1 << 17) - 1
        INF = 10**9
        m = len(andValues)

        dp = [{} for _ in range(m + 1)]
        dp[0][ALL_ONES] = 0

        for num in nums:
            for j in range(m - 1, -1, -1):
                dp_j = dp[j]
                if not dp_j:
                    continue

                target = andValues[j]
                new_dp_j = {}
                dp_j_next = dp[j + 1]

                for mask, cost in dp_j.items():
                    new_mask = mask & num

                    if cost < new_dp_j.get(new_mask, INF):
                        new_dp_j[new_mask] = cost

                    if new_mask == target:
                        new_cost = cost + num
                        if new_cost < dp_j_next.get(ALL_ONES, INF):
                            dp_j_next[ALL_ONES] = new_cost

                dp[j] = new_dp_j

        return dp[m].get(ALL_ONES, -1)

