class Solution:
    def findAnswer(self, n: int, edges: List[List[int]]) -> List[bool]:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        INF = 10**18
        heappop = heapq.heappop
        heappush = heapq.heappush

        def dijkstra(start):
            dist = [INF] * n
            dist[start] = 0
            pq = [(0, start)]
            while pq:
                d, u = heappop(pq)
                if d > dist[u]:
                    continue
                dist_u = dist[u]
                for v, w in adj[u]:
                    new_dist = dist_u + w
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        heappush(pq, (new_dist, v))
            return dist

        dist0 = dijkstra(0)
        D = dist0[n - 1]
        if D == INF:
            return [False] * len(edges)

        distN = dijkstra(n - 1)

        return [
            dist0[u] + w == D - distN[v] or dist0[v] + w == D - distN[u]
            for u, v, w in edges
        ]

