class Solution:
    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        N = len(nums)
        target = (N * (N + 1) + 2) // 4
        freq = defaultdict(int)

        def count_at_most(k: int) -> int:
            count = left = distinct = 0
            for right, val in enumerate(nums):
                if not freq[val]:
                    distinct += 1
                freq[val] += 1
                while distinct > k:
                    left_val = nums[left]
                    freq[left_val] -= 1
                    if not freq[left_val]:
                        distinct -= 1
                    left += 1
                count += right - left + 1
            freq.clear()
            return count

        low, high = 1, len(set(nums))
        while low < high:
            mid = (low + high) // 2
            if count_at_most(mid) >= target:
                high = mid
            else:
                low = mid + 1
        return low

