class Solution:
    def minAnagramLength(self, s: str) -> int:
        n = len(s)
        unique_chars = set(s)
        total_counts = {c: s.count(c) for c in unique_chars}

        def check(L: int) -> bool:
            k = n // L
            if any(v % k != 0 for v in total_counts.values()):
                return False

            target = {c: s.count(c, 0, L) for c in unique_chars}
            for block in range(1, k):
                start = block * L
                end = start + L
                if any(s.count(c, start, end) != count for c, count in target.items()):
                    return False
            return True

        small = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                if check(i):
                    return i
                if i * i != n:
                    small.append(n // i)

        for L in reversed(small):
            if check(L):
                return L

        return n

