class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        INF = float('inf')

        # Flat arrays for best_all to avoid tuple/list allocation overhead
        best_all_len1 = [-INF] * (k + 1)
        best_all_val1 = [-1] * (k + 1)
        best_all_len2 = [-INF] * (k + 1)
        best_all_val2 = [-1] * (k + 1)

        best_same = [{} for _ in range(k + 1)]
        ans = 0

        for num in nums:
            for j in range(k + 1):
                # Option 1: extend a subsequence ending with the same value
                res = best_same[j].get(num, -INF) + 1

                # Base case: start a new subsequence
                if j == 0:
                    if res < 1:
                        res = 1
                else:
                    # Option 2: extend a subsequence ending with a different value
                    L1 = best_all_len1[j - 1]
                    if best_all_val1[j - 1] != num:
                        val = L1 + 1
                    else:
                        val = best_all_len2[j - 1] + 1

                    if val > res:
                        res = val

                if res > ans:
                    ans = res

                # Update states if a valid subsequence length is found
                if res > 0:
                    if res > best_same[j].get(num, 0):
                        best_same[j][num] = res

                    # Update best_all (maintain top 2 with different ending values)
                    L1 = best_all_len1[j]
                    V1 = best_all_val1[j]
                    if res > L1:
                        if num == V1:
                            best_all_len1[j] = res
                        else:
                            best_all_len2[j] = L1
                            best_all_val2[j] = V1
                            best_all_len1[j] = res
                            best_all_val1[j] = num
                    elif num != V1 and res > best_all_len2[j]:
                        best_all_len2[j] = res
                        best_all_val2[j] = num

        return ans

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        best = [{} for _ in range(k + 1)]
        top1_val = [0] * (k + 1)
        top1_key = [-1] * (k + 1)
        top2_val = [0] * (k + 1)
        top2_key = [-1] * (k + 1)

        ans = 0

        for num in nums:
            for j in range(k + 1):
                best_j = best[j]
                if num in best_j:
                    dp_j = best_j[num] + 1
                else:
                    dp_j = 1

                if j > 0:
                    if top1_key[j - 1] != num:
                        val = top1_val[j - 1] + 1
                    else:
                        val = top2_val[j - 1] + 1
                    if val > dp_j:
                        dp_j = val

                if dp_j > ans:
                    ans = dp_j

                best_j[num] = dp_j
                if dp_j > top1_val[j]:
                    if top1_key[j] != num:
                        top2_val[j], top2_key[j] = top1_val[j], top1_key[j]
                    top1_val[j], top1_key[j] = dp_j, num
                elif top1_key[j] != num and dp_j > top2_val[j]:
                    top2_val[j], top2_key[j] = dp_j, num

        return ans

