class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7

        req = [-1] * (n + 1)
        max_c = 0
        for end_i, cnt_i in requirements:
            req[end_i + 1] = cnt_i
            if cnt_i > max_c:
                max_c = cnt_i

        dp = [0] * (max_c + 1)
        dp[0] = 1
        pref = [0] * (max_c + 2)
        zeros = [0] * (max_c + 1)

        for j in range(1, n + 1):
            p = 0
            for c in range(max_c + 1):
                p += dp[c]
                pref[c + 1] = p

            limit = j if j <= max_c else max_c + 1

            for c in range(limit):
                dp[c] = pref[c + 1] % MOD

            for c in range(limit, max_c + 1):
                dp[c] = (pref[c + 1] - pref[c - j + 1]) % MOD

            target = req[j]
            if target != -1:
                val = dp[target] if target <= max_c else 0
                dp[:] = zeros
                if target <= max_c:
                    dp[target] = val

        return dp[req[n]]

