class Solution:
    def minimumSum(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        P = [[0] * (m + 1) for _ in range(n + 1)]
        for r, row in enumerate(grid):
            P_r1 = P[r + 1]
            P_r = P[r]
            for c, val in enumerate(row):
                P_r1[c + 1] = P_r[c + 1] + P_r1[c] - P_r[c] + val

        def get_area(r1, r2, c1, c2):
            min_r = -1
            for r in range(r1, r2):
                if P[r+1][c2] - P[r][c2] - P[r+1][c1] + P[r][c1]:
                    min_r = r
                    break
            if min_r < 0:
                return 0

            max_r = min_r
            for r in range(r2 - 1, min_r, -1):
                if P[r+1][c2] - P[r][c2] - P[r+1][c1] + P[r][c1]:
                    max_r = r
                    break

            min_c = -1
            P_r1, P_r2 = P[r1], P[r2]
            for c in range(c1, c2):
                if P_r2[c+1] - P_r1[c+1] - P_r2[c] + P_r1[c]:
                    min_c = c
                    break

            max_c = min_c
            for c in range(c2 - 1, min_c, -1):
                if P_r2[c+1] - P_r1[c+1] - P_r2[c] + P_r1[c]:
                    max_c = c
                    break

            return (max_r - min_r + 1) * (max_c - min_c + 1)

        def calc(a1, a2, a3):
            return a1 + a2 + a3 + (not a1) + (not a2) + (not a3)

        ans = float('inf')

        for i in range(1, n - 1):
            for j in range(i + 1, n):
                ans = min(ans, calc(get_area(0, i, 0, m), get_area(i, j, 0, m), get_area(j, n, 0, m)))

        for i in range(1, m - 1):
            for j in range(i + 1, m):
                ans = min(ans, calc(get_area(0, n, 0, i), get_area(0, n, i, j), get_area(0, n, j, m)))

        for i in range(1, n):
            for j in range(1, m):
                ans = min(ans, calc(get_area(0, i, 0, m), get_area(i, n, 0, j), get_area(i, n, j, m)))
                ans = min(ans, calc(get_area(0, i, 0, j), get_area(0, i, j, m), get_area(i, n, 0, m)))
                ans = min(ans, calc(get_area(0, n, 0, j), get_area(0, i, j, m), get_area(i, n, j, m)))
                ans = min(ans, calc(get_area(0, i, 0, j), get_area(i, n, 0, j), get_area(0, n, j, m)))

        return ans

