class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        def f(r, b):
            k_r = math.isqrt(r)
            k_b = (math.isqrt(1 + 4 * b) - 1) // 2
            return 2 * min(k_r, k_b) + (k_r > k_b)

        return max(f(red, blue), f(blue, red))

