        if not nums:
            return 1

        it = iter(nums)
        first = next(it)
        prev_parity = first % 2
        even_count = 1 - prev_parity
        changes = 0

        for num in it:
            parity = num % 2
            even_count += 1 - parity
            if parity != prev_parity:
                changes += 1
            prev_parity = parity

        return max(1 + changes, max(even_count, len(nums) - even_count))

