class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        chars = set(target)
        for word in words:
            chars.update(word)
        chars = list(chars)
        char_to_idx = {ch: i for i, ch in enumerate(chars)}
        num_chars = len(chars)

        goto = [-1] * num_chars
        fail = [0]
        word_info = [{}]

        for word, cost in zip(words, costs):
            node = 0
            for ch in word:
                idx = char_to_idx[ch]
                pos = node * num_chars + idx
                if goto[pos] == -1:
                    goto[pos] = len(fail)
                    goto.extend([-1] * num_chars)
                    fail.append(0)
                    word_info.append({})
                node = goto[pos]
            l = len(word)
            wi = word_info[node]
            if l not in wi or cost < wi[l]:
                wi[l] = cost

        queue = deque()
        for idx in range(num_chars):
            if goto[idx] != -1:
                child = goto[idx]
                fail[child] = 0
                queue.append(child)
            else:
                goto[idx] = 0

        while queue:
            node = queue.popleft()
            node_pos = node * num_chars
            fail_pos = fail[node] * num_chars
            for idx in range(num_chars):
                pos = node_pos + idx
                if goto[pos] != -1:
                    child = goto[pos]
                    fail[child] = goto[fail_pos + idx]

                    fc = fail[child]
                    if fc:
                        wi_fc = word_info[fc]
                        if wi_fc:
                            wi = word_info[child]
                            for l, c in wi_fc.items():
                                if l not in wi or c < wi[l]:
                                    wi[l] = c

                    queue.append(child)
                else:
                    goto[pos] = goto[fail_pos + idx]

        for i in range(len(word_info)):
            wi = word_info[i]
            word_info[i] = list(wi.items()) if wi else None
        wi_lists = word_info

        target_indices = [char_to_idx[ch] for ch in target]

        n = len(target)
        INF = 10**9
        dp = [INF] * (n + 1)
        dp[0] = 0

        node = 0
        node_pos = 0
        for i, idx in enumerate(target_indices):
            node = goto[node_pos + idx]
            node_pos = node * num_chars

            wi = wi_lists[node]
            if wi:
                i1 = i + 1
                dp_i1 = dp[i1]
                for l, c in wi:
                    if l <= i1:
                        val = dp[i1 - l] + c
                        if val < dp_i1:
                            dp_i1 = val
                dp[i1] = dp_i1

        return dp[n] if dp[n] < INF else -1

