class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return 0

        P = self._compute_prefix_sums(grid, n)
        dp = self._initialize_dp(P[0], n)

        new_dp = [[0] * (n + 1) for _ in range(n + 1)]
        prefix_max = [0] * (n + 2)
        suffix_max = [0] * (n + 2)

        for j in range(1, n - 1):
            self._transition_dp(dp, P[j], n, new_dp, prefix_max, suffix_max)
            dp, new_dp = new_dp, dp

        return self._compute_answer(dp, P[n - 1], n)

    def _compute_prefix_sums(self, grid: List[List[int]], n: int) -> List[List[int]]:
        P = [[0] * (n + 1) for _ in range(n)]
        for j in range(n):
            s = 0
            for i in range(n):
                s += grid[i][j]
                P[j][i + 1] = s
        return P

    def _initialize_dp(self, P0: List[int], n: int) -> List[List[int]]:
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        for a in range(n + 1):
            pa = P0[a]
            for b in range(n + 1):
                v = P0[b] - pa
                dp[a][b] = v if v > 0 else 0
        return dp

    def _transition_dp(self, dp: List[List[int]], Pj: List[int], n: int, 
                       new_dp: List[List[int]], prefix_max: List[int], suffix_max: List[int]) -> None:
        for b in range(n + 1):
            pb = Pj[b]

            pm = sm = 0
            for a in range(n + 1):
                v = dp[a][b]
                if v > pm:
                    pm = v
                prefix_max[a + 1] = pm

                ra = n - a
                v = Pj[ra] - pb
                if v < 0:
                    v = 0
                v += dp[ra][b]
                if v > sm:
                    sm = v
                suffix_max[ra] = sm

            new_dp_b = new_dp[b]
            for c in range(n + 1):
                v = Pj[c] - pb
                if v < 0:
                    v = 0
                v += prefix_max[c + 1]
                sm_val = suffix_max[c + 1]
                new_dp_b[c] = v if v > sm_val else sm_val

    def _compute_answer(self, dp: List[List[int]], Pn: List[int], n: int) -> int:
        ans = 0
        for a in range(n + 1):
            pa = Pn[a]
            dp_a = dp[a]
            for b in range(n + 1):
                v = pa - Pn[b]
                if v < 0:
                    v = 0
                v += dp_a[b]
                if v > ans:
                    ans = v
        return ans

