class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        lower = math.isqrt(l)
        if lower * lower < l:
            lower += 1

        upper = math.isqrt(r)
        if lower > upper:
            return r - l + 1

        is_prime = bytearray(b'\x01') * (upper + 1)
        is_prime[0] = 0
        if upper:
            is_prime[1] = 0

        limit = math.isqrt(upper)
        for i in range(2, limit + 1):
            if is_prime[i]:
                start = i * i
                count = (upper - start) // i + 1
                is_prime[start : upper + 1 : i] = b'\x00' * count

        return r - l + 1 - sum(is_prime[lower : upper + 1])

