class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        m1 = m - 1
        n1 = n - 1

        base_cost = 0
        T_min = 0
        has_tied_2 = False

        for i in range((m + 1) // 2):
            i2 = m1 - i
            is_mid_i = i == i2
            row_i = grid[i]
            row_i2 = grid[i2]
            for j in range((n + 1) // 2):
                j2 = n1 - j
                is_mid_j = j == j2

                ones = row_i[j]
                if not is_mid_j:
                    ones += row_i[j2]
                if not is_mid_i:
                    ones += row_i2[j]
                    if not is_mid_j:
                        ones += row_i2[j2]

                s = 1 << (2 - is_mid_i - is_mid_j)
                zeros = s - ones

                if ones < zeros:
                    base_cost += ones
                else:
                    base_cost += zeros
                    if ones > zeros:
                        T_min += s

                if s == 2 and ones == 1:
                    has_tied_2 = True

        r = T_min % 4
        return base_cost + (r % 2 if has_tied_2 else r)

