class Solution:
    def distinctPrimeFactors(self, nums: List[int]) -> int:
        factors = set()
        for num in nums:
            if num % 2 == 0:
                factors.add(2)
                while num % 2 == 0:
                    num //= 2
            d = 3
            while d * d <= num:
                if num % d == 0:
                    factors.add(d)
                    while num % d == 0:
                        num //= d
                d += 2
            if num > 1:
                factors.add(num)
        return len(factors)

