class Solution:
    def minimumVisitedCells(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        row_heaps = [[] for _ in range(m)]
        col_heaps = [[] for _ in range(n)]
        INF = 10**9

        g0 = grid[0][0]
        if g0 > 0:
            heapq.heappush(row_heaps[0], (1, g0))
            heapq.heappush(col_heaps[0], (1, g0))

        dp_val = 1 if m == 1 and n == 1 else INF

        for i in range(m):
            r_heap = row_heaps[i]
            row_i = grid[i]
            for j in range(1 if i == 0 else 0, n):
                while r_heap and r_heap[0][1] < j:
                    heapq.heappop(r_heap)
                c_heap = col_heaps[j]
                while c_heap and c_heap[0][1] < i:
                    heapq.heappop(c_heap)

                dp_val = INF
                if r_heap:
                    dp_val = r_heap[0][0] + 1
                if c_heap and c_heap[0][0] + 1 < dp_val:
                    dp_val = c_heap[0][0] + 1

                g = row_i[j]
                if dp_val < INF and g > 0:
                    heapq.heappush(r_heap, (dp_val, j + g))
                    heapq.heappush(c_heap, (dp_val, i + g))

        return dp_val if dp_val < INF else -1

