class Solution:
    def findMaximumElegance(self, items: List[List[int]], k: int) -> int:
        items.sort(reverse=True)

        total_profit = 0
        seen = set()
        dups = []

        for i in range(k):
            profit, cat = items[i]
            total_profit += profit
            if cat in seen:
                dups.append(profit)
            else:
                seen.add(cat)

        distinct = len(seen)
        best = total_profit + distinct * distinct

        for i in range(k, len(items)):
            if not dups:
                break
            profit, cat = items[i]
            if cat in seen:
                continue
            seen.add(cat)
            total_profit += profit - dups.pop()
            distinct += 1
            elegance = total_profit + distinct * distinct
            if elegance > best:
                best = elegance

        return best

