class Solution:
    def maxSum(self, nums: List[int], m: int, k: int) -> int:
        if len(nums) < k:
            return 0

        freq = {}
        current_sum = 0
        max_sum = 0

        for i in range(k):
            num = nums[i]
            current_sum += num
            freq[num] = freq.get(num, 0) + 1

        if len(freq) >= m and current_sum > max_sum:
            max_sum = current_sum

        for i in range(k, len(nums)):
            in_num, out_num = nums[i], nums[i - k]
