class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        max_p = max(prices)

        left_max = [0] * n
        tree = [0] * (max_p + 1)

        for j in range(n):
            p = prices[j]
            res = 0
            i = p - 1
            while i > 0:
                t = tree[i]
                if t > res:
                    res = t
                i -= i & (-i)
            left_max[j] = res

            i = p
            val = profits[j]
            while i <= max_p:
                if val > tree[i]:
                    tree[i] = val
                i += i & (-i)

        tree = [0] * (max_p + 1)
        ans = -1

        for j in range(n - 1, -1, -1):
            p = prices[j]
            res = 0
            i = max_p - p
            while i > 0:
                t = tree[i]
                if t > res:
                    res = t
                i -= i & (-i)

            l = left_max[j]
            if l > 0 and res > 0:
                total = l + profits[j] + res
                if total > ans:
                    ans = total

            i = max_p - p + 1
            val = profits[j]
            while i <= max_p:
                if val > tree[i]:
                    tree[i] = val
                i += i & (-i)

        return ans

