class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        ords = bytes(ord(c) - 97 for c in word)
        result = 0
        start = 0

        for i in range(1, n + 1):
            if i == n or abs(ords[i] - ords[i - 1]) > 2:
                end = i
                L = end - start

                for num_chars in range(1, 27):
                    window_len = num_chars * k
                    if window_len > L:
                        break

                    freq = [0] * 26
                    valid_count = 0

                    for j in range(start, start + window_len):
                        c = ords[j]
                        f = freq[c]
                        if f == k:
                            valid_count -= 1
                        f += 1
                        freq[c] = f
                        if f == k:
                            valid_count += 1

                    if valid_count == num_chars:
                        result += 1

                    for j in range(start + window_len, end):
                        c = ords[j]
                        f = freq[c]
                        if f == k:
                            valid_count -= 1
                        f += 1
                        freq[c] = f
                        if f == k:
                            valid_count += 1

                        c = ords[j - window_len]
                        f = freq[c]
                        if f == k:
                            valid_count -= 1
                        f -= 1
                        freq[c] = f
                        if f == k:
                            valid_count += 1

                        if valid_count == num_chars:
                            result += 1

                start = i

        return result

