class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        ans = 0
        right_counts = defaultdict(int)
        for k in range(2, n):
            right_counts[nums[k] % d] += 1

        left_counts = defaultdict(int)
        left_counts[nums[0] % d] = 1

        for j in range(1, n - 1):
            target = (-nums[j]) % d

            for r, count in left_counts.items():
                ans += count * right_counts.get((target - r) % d, 0)

            rem_right = nums[j+1] % d
            right_counts[rem_right] -= 1
            if not right_counts[rem_right]:
                del right_counts[rem_right]

            left_counts[nums[j] % d] += 1

        return ans

