class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_pattern(text: str, pattern: str) -> List[int]:
            if not pattern or len(pattern) > len(text):
                return []

            fail = [0] * len(pattern)
            j = 0
            for i in range(1, len(pattern)):
                while j > 0 and pattern[i] != pattern[j]:
                    j = fail[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                fail[i] = j

            res = []
            j = 0
            m = len(pattern)
            for i, char in enumerate(text):
                while j > 0 and char != pattern[j]:
                    j = fail[j - 1]
                if char == pattern[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = fail[j - 1]
            return res

        indices_a = find_pattern(s, a)
        indices_b = find_pattern(s, b)

        res = []
        j = 0
        m = len(indices_b)
        for i in indices_a:
            while j < m and indices_b[j] < i - k:
                j += 1
            if j < m and indices_b[j] <= i + k:
                res.append(i)

        return res

