class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        return sum(x % (y * k) == 0 for x in nums1 for y in nums2)

from itertools import groupby

class Solution:
    def compressedString(self, word: str) -> str:
        _ = word[-1]
        parts = []
        for k, g in groupby(word):
            count = sum(1 for _ in g)
            while count > 0:
                c = min(count, 9)
                parts.append(f"{c}{k}")
                count -= c
        return "".join(parts)

class Solution:
    def minimumChairs(self, s: str) -> int:
        max_chairs = current_chairs = 0
        for c in s:
            current_chairs += (c == 'E') - (c == 'L')
            if current_chairs > max_chairs:
                max_chairs = current_chairs
        return max_chairs

class Solution:
    def countDays(self, days: int, meetings: List[List[int]]) -> int:
        meetings.sort()
        it = iter(meetings)
        start, end = next(it)
        meeting_days = 0

        for s, e in it:
            if s > end + 1:
                meeting_days += end - start + 1
                start, end = s, e
            elif e > end:
                end = e

        return days - meeting_days - end + start - 1

class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        ans = float('inf')
        prev_ors = set()
        for num in nums:
            prev_ors = {v | num for v in prev_ors}
            prev_ors.add(num)
            for val in prev_ors:
                if (diff := abs(k - val)) < ans:
                    ans = diff
                    if not ans:
                        return 0
        return ans

from itertools import pairwise

class Solution:
    def orArray(self, nums: List[int]) -> List[int]:
        return [a | b for a, b in pairwise(nums)]

class Solution:
    def clearDigits(self, s: str) -> str:
        res = []
        for c in s:
            if c.isdigit():
                res.pop()
            else:
                res.append(c)
        return "".join(res)

class Solution:
    def numberOfChild(self, n: int, k: int) -> int:
        c = 2 * (n - 1)
        t = k % c
        return min(t, c - t)

from math import comb

class Solution:
    def valueAfterKSeconds(self, n: int, k: int) -> int:
        return comb(n + k - 1, k) % 1000000007

from typing import List
from collections import Counter

class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        freq = Counter(h % 24 for h in hours)
        return sum(freq[r] * freq[24 - r] for r in range(1, 12)) + freq[0] * (freq[0] - 1) // 2 + freq[12] * (freq[12] - 1) // 2

class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        bit = [0] * (n + 1)
        peak_status = bytearray(n)

        for i in range(1, n - 1):
            if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                peak_status[i] = True
                idx = i + 1
                while idx <= n:
                    bit[idx] += 1
                    idx += idx & (-idx)

        result = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if l + 1 < r:
                    s = 0
                    idx = r
                    while idx > 0:
                        s += bit[idx]
                        idx -= idx & (-idx)
                    idx = l + 1
                    while idx > 0:
                        s -= bit[idx]
                        idx -= idx & (-idx)
                    result.append(s)
                else:
                    result.append(0)
            else:
                idx, val = q[1], q[2]
                nums[idx] = val

                for i in range(idx - 1, idx + 2):
                    if 0 < i < n - 1:
                        new_status = nums[i] > nums[i - 1] and nums[i] > nums[i + 1]
                        if new_status != peak_status[i]:
                            peak_status[i] = new_status
                            delta = 1 if new_status else -1
                            bit_idx = i + 1
                            while bit_idx <= n:
                                bit[bit_idx] += delta
                                bit_idx += bit_idx & (-bit_idx)

        return result

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])

        min_r = next((r for r in range(rows) if 1 in grid[r]), rows)
        max_r = rows - 1 - next((r for r in range(rows - 1, -1, -1) if 1 in grid[r]), rows)

        min_c = next((c for c in range(cols) if any(grid[r][c] == 1 for r in range(min_r, max_r + 1))), cols)
        max_c = cols - 1 - next((c for c in range(cols - 1, -1, -1) if any(grid[r][c] == 1 for r in range(min_r, max_r + 1))), cols)

        return (max_r - min_r + 1) * (max_c - min_c + 1)

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        for j in range(1, n):
            nums_j = nums[j]
            best = 0
            i_nj = nums_j
            for i in range(1, j):
                val = dp[i] - i_nj
                if val > best:
                    best = val
                i_nj += nums_j
            res = best + i_nj
            dp[j] = res if res > 0 else 0
        return dp[-1]

from typing import List

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        ans = 0
        prev = {}

        for x in nums:
            curr = {x: 1} if x >= k else {}
            for val, cnt in prev.items():
                if (new_val := val & x) >= k:
                    curr[new_val] = curr.get(new_val, 0) + cnt

            prev = curr
            ans += curr.get(k, 0)

        return ans

class Solution:
    def modifiedList(self, nums: List[int], head: Optional[ListNode]) -> Optional[ListNode]:
        nums_set = set(nums)
        current = dummy = ListNode(0, head)

        while (nxt := current.next):
            if nxt.val in nums_set:
                current.next = nxt.next
            else:
                current = nxt

        return dummy.next
